import {cards,relics,cardCost,recoveryCount,runDistance,canStep,stages,options,apply,damage,goal} from './rules.mjs?v=4';
export const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('ar-SA',{useGrouping:false});export const num=n=>nf.format(n);
export const ratio=(a,b)=>`<bdi dir="ltr" class="number">${num(a)} / ${num(b)}</bdi>`;
export const button=(label,action,cls='',disabled=false)=>`<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`;
const drawings={run:'M5 19l5-6 4 2 5-8M10 13l-1-5 5-3 3 3 4 1M9 8l-4 2M14 15l-1 6M14 3h.01',arrow:'M4 20L20 4M12 4h8v8M4 14v6h6',knife:'M5 19l5-5M8 16l-3-3M10 14l8-10 2 2-6 10z',cover:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 11l3 3 5-6',feint:'M3 8c8-12 8 18 18 6M3 14c8-12 8 10 18-6',breath:'M5 8a8 8 0 1 1-1 7M5 3v5h5',bag:'M8 3h8l-2 5c9 7 9 13-2 13S1 15 10 8zM9 8h6',friend:'M9 6a3 3 0 1 0 6 0a3 3 0 1 0-6 0M6 21v-7c0-5 12-5 12 0v7M9 15v6M15 15v6',exit:'M14 4H4v16h10M10 12h12M18 8l4 4-4 4'};
export const icon=(id)=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="icon"><path d="${drawings[id]||drawings.cover}"/></svg>`;
const pips=(value,total,ghost=value)=>`<span class="pips" aria-label="${num(value)} من ${num(total)}">${Array.from({length:total},(_,i)=>`<i class="${i<value?'filled':i<ghost?'ghost':''}"></i>`).join('')}</span>`;
export function cardSummary(s,id){if(!s.ready.includes(id))return `تعود بعد ${num(Math.ceil((s.queue.indexOf(id)+1)/recoveryCount(s)))} دور`;if(s.ap<cardCost(s,id))return 'انتهت أفعالك';if(!options(s,id).length)return id==='breath'?'الطابور فارغ':'لا هدف متاح';return {run:(runDistance(s)===2?'اعبر خطوتين':'اعبر ٣ خطوات')+(cardCost(s,id)===0?' · مجانًا':''),arrow:s.phase==='retreat'?'احجب ٤ ضرر':s.phase==='duel'?'قوة الحارس −٢':'حرس −٢ · إيقاف الحامل',knife:s.relic==='blade'?'ضربة ٣ · يبقى في يدك':s.phase==='strike'?'هاجم أو اقطع القيد':'ضربة ٣ · صحتك −١',cover:s.phase==='strike'?'احمِ نفسك أو رفيقك':'احجب ٥ ضرر',feint:'إنذار −٢ · حجب ٢',breath:'استعد بطاقة الآن'}[id];}
export function objective(s){return s.phase==='duel'?'اهزم الحارس أو اعبر الممر':s.phase==='approach'?'بلغ القافلة':s.phase==='strike'?s.loot?'الزاد معك؛ أخرج رفيقك وارجع':s.lootLost?'القافلة ابتعدت؛ عد حيًّا':'خذ الزاد وأخرج رفيقك':'بلغ المخبأ';}
export function coachText(s,lesson){if(lesson===0)return 'ابدأ بحركة: اضغط بطاقة «عَدْو».';if(lesson===1)return 'شاهد أثر الحركة، ثم اضغط «تنفيذ».';if(lesson===2)return '«عَدْو» في الطابور الآن. بقي لك فعل واحد.';if(lesson===3)return 'اضغط «إنهاء الدور» لتعود أول بطاقة في الطابور.';if(s.ap===0)return options(s,'run').length?'العَدْو ما زال مجانيًا؛ يمكنك استخدامه الآن.':'انتهت أفعالك؛ أنهِ الدور للاستعادة.';if(s.phase==='duel')return 'الحركة تعبر الممر؛ الضرب يضعف الحارس حتى تهزمه.';if(s.phase==='strike'&&s.loot&&s.rescue>=3)return 'معك الزاد والرفيق. ابدأ العودة متى شئت.';return 'اختر بطاقة، ثم اختر مَن تؤثر فيه.';}
export function renderGame(s,{pending=null,lesson=4,feedback=''}={}){const n=pending?apply(s,pending):s,phaseChange=n.phase!==s.phase,showProgress=phaseChange&&!(s.phase==='duel'&&n.guards===0)?goal(s):n.progress;
 const actionText=s.ap===2?'فعلان متاحان':s.ap===1?'فعل واحد متبقٍّ':'لا أفعال متبقية';
 const moveAllowed=canStep(s),recoverNames=s.queue.slice(0,recoveryCount(s)).map(id=>cards[id].name).join(' + ');
 const friendText=!s.friendHp?'سقط':s.rescue>=3?'معك':s.phase==='duel'?'بقي عند القافلة':s.phase==='approach'?'يقترب من الجهة الأخرى':s.phase==='retreat'?'بقي عند القافلة':`تحريره ${num(s.rescue)} من ٣`;
 const next=apply(s,{type:'end'}),friendDamage=s.friendHp-next.friendHp;
 return `<div class="game"><header class="top"><span class="brand">الشنفرى <small>طريق العودة</small></span><span class="turn">الدور ${num(s.turn)}</span>${button('⋯','help','icon-button')}</header><div class="hud" aria-label="حالتك"><div class="vital"><span>الصحة</span><strong data-feedback="hp">${ratio(s.hp,16)}</strong><span class="hp-track"><i style="width:${s.hp/16*100}%"></i></span></div><div class="action-count" data-feedback="ap">${pips(s.ap,2)}<span>${actionText}</span></div><button class="alarm" data-action="alarm" aria-label="الإنذار ${num(s.alarm)} من ٦؛ اعرف أثره">إنذار <bdi dir="ltr">${num(s.alarm)}</bdi> ${s.alarm>=3?'!':''}</button></div><div class="mission"><h1>${objective(s)}</h1><span>${s.campaign?`<small>المواجهة ${num(s.encounter)} من ٢</small>`:['approach','strike','retreat'].map((p,i)=>`<i class="${p===s.phase?'active':''}">${num(i+1)}</i>`).join('')}</span></div><section class="board" aria-label="أهداف الموقف"><div class="board-atmosphere" aria-hidden="true"><span class="figure"></span><span class="figure foe"></span></div><div class="route" data-feedback="progress"><div><span>${s.phase==='strike'?'بلوغ الزاد':s.phase==='retreat'?'طريق المخبأ':s.phase==='duel'?'عبور الممر':'طريق القافلة'}</span><strong>${ratio(s.progress,goal(s))}</strong></div>${pips(s.progress,goal(s),showProgress)}${phaseChange?`<small class="good">بعد الحركة: ${n.screen==='reward'?'المكافأة':n.phase==='end'?'تصل للمخبأ':stages[n.phase]}</small>`:s.phase==='strike'&&!s.loot&&!s.lootLost?`<small>${s.pin?'الحامل معطّل '+num(s.pin)+' دور': 'تهرب القافلة بعد '+num(5-s.strikeTurns)+' أدوار'}</small>`:(s.phase==='retreat'||s.phase==='duel')&&s.loot?'<small>الغنيمة تثقل العَدْو: خطوتان بدل ٣</small>':''}</div><div class="world-targets"><button data-action="inspect-loot" class="world-target ${s.loot?'done':''} ${pending?.target==='move'||pending?.target==='carrier'?'targeted':''}">${icon('bag')}<strong>${s.loot?'الزاد معك':s.lootLost?'فقدت الزاد':'الزاد'}</strong><small>${s.phase==='approach'?'عند القافلة':s.loot?'احمله للمخبأ':s.phase==='duel'?'لم تأخذه في الغارة':s.lootLost?'ابتعدت القافلة': 'تحتاج '+num(Math.max(0,4-s.progress))+' خطوات'}</small></button><button data-action="inspect-friend" class="world-target ${s.rescue>=3?'done':''} ${pending?.target==='friend'?'targeted':''}" data-feedback="friend">${icon('friend')}<strong>رفيقك ${s.phase==='duel'&&s.rescue<3?'ليس معك':ratio(s.friendHp,5)}</strong><small>${friendText}</small>${s.phase==='strike'&&s.rescue<3?pips(s.rescue,3,n.rescue):''}</button><button data-action="inspect-guard" class="world-target ${pending?.target==='guard'?'targeted':''}" data-feedback="guard">${icon('arrow')}<strong>${s.phase==='retreat'?'المطاردون':s.phase==='duel'?'حارس الممر':'الحرس'}</strong><small>${s.phase==='retreat'?'خلفك':s.guards?'قوة '+num(s.guards):'عطّلتهم'}</small>${s.phase!=='retreat'?pips(s.guards,s.phase==='duel'?8:4):''}</button></div></section><div class="threat ${damage(s)===0?'safe':''}"><span>إذا أنهيت الدور</span><strong data-feedback="damage">${damage(s)?'−'+num(damage(s))+' صحة':'محميّ'}</strong>${friendDamage>0&&s.phase==='strike'&&s.rescue<3?`<small>رفيقك −${num(friendDamage)}</small>`:''}<span class="recover-label">${s.queue.length?'تعود '+recoverNames:'لا بطاقة تنتظر'}</span></div><div class="coach ${lesson<4?'learning':''}" role="status"><span>${esc(feedback||coachText(s,lesson))}</span>${lesson<4?button('تخطي','skip','text-button'):''}</div><section class="dock" aria-label="بطاقاتك"><div class="dock-heading"><h2>بطاقاتك</h2><small>${s.relic?button(relics[s.relic].name,'inspect-relic','text-button relic-badge'):'استخدام البطاقة = فعل'}</small>${moveAllowed?button('خطوة بلا بطاقة','step','text-button'):''}</div><div class="hand">${Object.keys(cards).map(id=>{const ready=s.ready.includes(id),legal=options(s,id).length;return `<button class="card ${!ready?'waiting':''} ${((lesson===0&&id==='run')||(s.relic==='wind'&&s.ap===0&&id==='run'&&legal))?'guided':''}" data-card="${id}" aria-label="${cards[id].name}: ${cardSummary(s,id)}" ${!legal?'disabled':''}>${icon(id)}<strong>${cards[id].name}</strong><small>${cardSummary(s,id)}</small>${ready?`<span class="cost" aria-label="التكلفة ${num(cardCost(s,id))} فعل">${num(cardCost(s,id))}</span>`:'<span class="cost">↺</span>'}</button>`;}).join('')}</div><div class="queue-line"><span>الاستعادة</span><div class="queue" aria-label="الأولى تعود عند نهاية الدور">${s.queue.length?s.queue.map((id,i)=>`<span class="queued ${i<recoveryCount(s)?'first':''}" data-queued="${id}"><b>${i<recoveryCount(s)?'التالية':num(i+1)}</b> ${cards[id].name}</span>`).join(''):'<small>البطاقات المستخدمة تنتظر هنا</small>'}</div></div><footer class="endbar">${s.phase==='strike'?button(`${icon('exit')} انسحاب`,'retreat','secondary'):(s.phase==='retreat'||s.phase==='duel')&&s.loot?button('اترك الزاد','drop','secondary'):''}${s.assist?button('مساندة الرفيق','assistance','secondary'):''}${button(`إنهاء الدور <small>${s.queue.length?'↺ '+recoverNames:'إنذار +١'}</small>`,'end',(s.ap===0&&!options(s,'run').length)||lesson===3?'primary':'end-turn')}</footer></section><span class="sr" aria-live="polite">الصحة ${num(s.hp)}، ${actionText}، ضرر نهاية الدور ${num(damage(s))}</span></div>`;
}
export function changes(s,n,a){const list=[];for(const [k,label] of [['hp','صحتك'],['friendHp','صحة رفيقك'],['alarm','الإنذار'],['guards','قوة الحرس'],['rescue','تحرير الرفيق']])if(s[k]!==n[k])list.push(`<span>${label} <bdi dir="ltr">${num(s[k])} → ${num(n[k])}</bdi></span>`);if(n.phase!==s.phase)list.push(`<span>${n.phase==='end'?n.outcome==='dead'?'تسقط بهذه الحركة':n.screen==='reward'?'تنجو وتختار مكافأتك':s.phase==='duel'?'تفتح طريق المخبأ':'تبلغ المخبأ': 'تنتقل إلى '+stages[n.phase]}</span>`);else if(n.progress!==s.progress)list.push(`<span>التقدم <bdi dir="ltr">${num(s.progress)} → ${num(n.progress)}</bdi></span>`);if(n.pin>s.pin)list.push('<span>الحامل يتوقف دورين</span>');if(n.block>s.block)list.push(`<span>حجب ${num(n.block-s.block)} هذا الدور</span>`);if(a?.card==='breath')list.push(`<span>تستعيد ${cards[a.target].name} الآن</span>`);if(a?.type==='end')list.push(`<span>${s.queue.length?'تستعيد '+s.queue.slice(0,recoveryCount(s)).map(id=>cards[id].name).join(' + '):'لا بطاقة للاستعادة'}</span>`);return list.join('');}

export function renderReward(s){return `<main class="reward-screen"><p class="eyebrow">المواجهة الأولى مكتملة</p><h1>أثر يغيّر القاعدة</h1><p>اختر أثرًا واحدًا يرافقك في المواجهة الثانية.</p><div class="reward-carry"><span>صحتك ${ratio(s.hp,16)} ← تستعيد ${num(Math.min(6,16-s.hp))}</span><span>الزاد: ${s.loot?'معك':'ضاع'} · الرفيق: ${s.rescue>=3&&s.friendHp>0?'معك':'ليس معك'}</span></div><div class="relic-choices">${Object.entries(relics).map(([id,r])=>`<button data-relic="${id}" class="relic-choice">${icon(r.icon)}<strong>${r.name}</strong><small>${r.before}</small><b>${r.after}</b><span>${r.rule}</span></button>`).join('')}</div><div class="next-encounter"><h2>التالي: حارس الممر</h2><p>اهزمه أو اعبر من جانبه. نفس البطاقات؛ أثرك يغيّر طريقة استخدامها.</p><small>تجهز جميع البطاقات وينخفض الإنذار إلى ١.</small></div>${button('تقرير المواجهة الأولى','report','text-button')}</main>`;}
